mapper.select:
SELECT id, 'ARCHIVE_ACCESS_APPROVAL' AS source_type, use_type AS title, employee_id, status,
       NULL AS due_at, created_at
FROM archive_access_application
WHERE (
    1 = 1
    target_department_id = #{departmentId}
    employee_id = #{employeeId}
    1 = 0
)
  AND ((status = 'PENDING_DEPT_APPROVAL' AND current_node = 'DEPT_APPROVAL')
    OR (status = 'PENDING_HR_APPROVAL' AND current_node = 'HR_APPROVAL'))
ORDER BY created_at DESC, id DESC LIMIT #{limit}

SELECT u.id, 'ARCHIVE_RETURN_DUE' AS source_type,
       CONCAT('Return archive ', a.application_no) AS title, a.employee_id, u.status,
       u.due_at, u.created_at
FROM archive_use_record u
JOIN archive_access_application a ON a.id = u.application_id
WHERE u.status = 'IN_USE' AND u.due_at <= #{dueSoonUntil}
  AND (
    1 = 1
    a.target_department_id = #{departmentId}
    a.employee_id = #{employeeId}
    1 = 0
  )
ORDER BY u.due_at ASC, u.created_at DESC, u.id DESC LIMIT #{limit}
